import sanitizeHtml from 'sanitize-html';

// Server-side sanitizer for post HTML generated by draftjs-to-html.
// Runs in getStaticProps, so pages render pre-sanitized HTML. This replaces
// isomorphic-dompurify, whose jsdom dependency chain fails to load in the
// Vercel runtime (ERR_REQUIRE_ESM from html-encoding-sniffer).
export function sanitizePostHtml(html: string): string {
    return sanitizeHtml(html, {
        allowedTags: sanitizeHtml.defaults.allowedTags.concat(['img', 'ins', 'del', 'h1', 'h2']),
        allowedAttributes: {
            ...sanitizeHtml.defaults.allowedAttributes,
            a: ['href', 'name', 'target', 'rel'],
            img: ['src', 'alt', 'width', 'height', 'style'],
            p: ['style'],
            h1: ['style'], h2: ['style'], h3: ['style'], h4: ['style'], h5: ['style'], h6: ['style'],
            span: ['style'],
        },
        allowedStyles: {
            '*': {
                'text-align': [/^(left|right|center|justify)$/],
                'height': [/^\d+(px|%)?$/, /^auto$/],
                'width': [/^\d+(px|%)?$/, /^auto$/],
                'float': [/^(left|right|none)$/],
            },
        },
        allowedSchemes: ['http', 'https', 'mailto'],
    });
}
